#!/usr/bin/env python3
import datetime, hashlib, json, os, sys, time, uuid
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
from aws_cli import observe
ACCOUNT='000000000000'; REGION='us-east-1'
PREFIX='stackd-sns-ctsrc-'+uuid.uuid4().hex[:12]
OUT=Path('testdata/aws/sns/encryption_cloudtrail_source.json')
ENV=dict(os.environ,AWS_DEFAULT_REGION=REGION,AWS_REGION=REGION,AWS_MAX_ATTEMPTS='2',AWS_PAGER='')
for k in list(ENV):
    if k.startswith('AWS_ENDPOINT_URL'): del ENV[k]
START=time.time()
CAP={'account':ACCOUNT,'region':REGION,'prefix':PREFIX,'started_ms':int(START*1000),'source_references':['https://docs.aws.amazon.com/awscloudtrail/latest/userguide/cloudtrail-permissions-for-sns-notifications.html','https://docs.aws.amazon.com/awscloudtrail/latest/userguide/configure-sns-notifications-for-cloudtrail.html','https://docs.aws.amazon.com/sns/latest/dg/sns-key-management.html'],'source_revisions':{'stackd':'6c8e6a39e279a7bd64483c78d788cf5fc2a2e9cf'},'observations':[],'receipts':[],'windows':[],'cloudtrail':{'events':[],'lookups':[]},'cleanup':[],'owned_resources':{},'limitations':['Single-region standard-topic CloudTrail producer; validation publication and, only if necessary, bounded management-event log notifications. No organization mutation, data-event logging, or Lake.','SNS source CMK is used only by the owned SNS topic. Owned bucket uses SSE-S3, queue is unencrypted, and trail has no KmsKeyId.','The source service alone receives GenerateDataKey/Decrypt permission, scoped by topic encryption context; there is no sns.amazonaws.com KMS Allow. Topic and queue service grants require their exact source ARN and account.']}
R=CAP['owned_resources']; TRAIL='arn:aws:cloudtrail:'+REGION+':'+ACCOUNT+':trail/'+PREFIX; TOPIC='arn:aws:sns:'+REGION+':'+ACCOUNT+':'+PREFIX

def ms(): return int(time.time()*1000)
def save(): OUT.write_text(json.dumps(CAP,indent=2)+'\n')
def call(label,service,operation,args=None,strict=True,cleanup=False):
    item={'label':label,'service':service,'operation':operation,'input':args or {},'request_started_ms':ms()}
    try: result=observe(service,operation,args,ENV)
    except Exception as e:
        item.update(transport_error=str(e),response_observed_ms=ms()); CAP['cleanup' if cleanup else 'observations'].append(item); save(); raise
    item.update(result=result,response_observed_ms=ms()); CAP['cleanup' if cleanup else 'observations'].append(item); save()
    if strict and result['code']!='Success': raise RuntimeError(label+': '+json.dumps(result))
    return result.get('output',{}) if strict else result

def policy(statements): return json.dumps({'Version':'2012-10-17','Statement':statements})
def receive(label,seconds):
    start=ms(); deadline=time.monotonic()+seconds; found=False
    while time.monotonic()<deadline and not found:
        out=call('receive-'+label,'sqs','receive-message',{'QueueUrl':R['queue_url'],'WaitTimeSeconds':10,'MaxNumberOfMessages':10,'MessageAttributeNames':['All'],'MessageSystemAttributeNames':['All']})
        for m in out.get('Messages',[]):
            body=m['Body']; parsed=None
            try: parsed=json.loads(body)
            except json.JSONDecodeError: pass
            is_validation=body=='CloudTrail validation message.'
            is_log=isinstance(parsed,dict) and parsed.get('s3Bucket')==PREFIX
            CAP['receipts'].append({'observed_ms':ms(),'phase':label,'queue_arn':R['queue_arn'],'topic_arn':R['topic_arn'],'message':m,'decoded_body':parsed,'is_cloudtrail_validation':is_validation,'is_owned_log_notification':is_log,'correlation':{'exclusive_subscribed_topic':R['topic_arn'],'topic_policy_source_arn':TRAIL,'topic_policy_source_account':ACCOUNT,'producer_observation':'create-trail','only_publisher_in_probe':'cloudtrail.amazonaws.com'}})
            call('delete-receipt','sqs','delete-message',{'QueueUrl':R['queue_url'],'ReceiptHandle':m['ReceiptHandle']})
            found=found or is_validation or is_log
    CAP['windows'].append({'phase':label,'started_ms':start,'ended_ms':ms(),'maximum_seconds':seconds,'matching_receipt':found}); save(); return found

def cleanup_one(label,service,op,args):
    try: return call(label,service,op,args,strict=False,cleanup=True)
    except Exception as e:
        CAP.setdefault('cleanup_transport_failures',[]).append({'label':label,'error':str(e)}); save(); return {}

try:
    CAP['identity']=call('identity-before-mutation','sts','get-caller-identity')
    if CAP['identity']['Account']!=ACCOUNT: raise RuntimeError('Unexpected account; mutation forbidden')
    R['key']=call('create-sns-source-key','kms','create-key',{'Description':PREFIX,'Policy':policy([{'Sid':'OwnerAdministration','Effect':'Allow','Principal':{'AWS':'arn:aws:iam::'+ACCOUNT+':root'},'Action':'kms:*','Resource':'*'},{'Sid':'CloudTrailSnsOnly','Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':['kms:GenerateDataKey*','kms:Decrypt'],'Resource':'*','Condition':{'StringEquals':{'kms:EncryptionContext:aws:sns:topicArn':TOPIC}}}]),'Tags':[{'TagKey':'stackd-probe','TagValue':PREFIX}]})['KeyMetadata']; save()
    call('read-source-key-policy','kms','get-key-policy',{'KeyId':R['key']['KeyId'],'PolicyName':'default'})
    R['queue_url']=call('create-queue','sqs','create-queue',{'QueueName':PREFIX,'Attributes':{'SqsManagedSseEnabled':'false'}})['QueueUrl']; save()
    R['queue_arn']=call('read-queue','sqs','get-queue-attributes',{'QueueUrl':R['queue_url'],'AttributeNames':['QueueArn','SqsManagedSseEnabled']})['Attributes']['QueueArn']; save()
    call('queue-source-policy','sqs','set-queue-attributes',{'QueueUrl':R['queue_url'],'Attributes':{'Policy':policy([{'Effect':'Allow','Principal':{'Service':'sns.amazonaws.com'},'Action':'sqs:SendMessage','Resource':R['queue_arn'],'Condition':{'ArnEquals':{'aws:SourceArn':TOPIC},'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])}})
    R['topic_arn']=call('create-encrypted-topic','sns','create-topic',{'Name':PREFIX,'Attributes':{'KmsMasterKeyId':R['key']['Arn']}})['TopicArn']; save()
    call('topic-source-policy','sns','set-topic-attributes',{'TopicArn':TOPIC,'AttributeName':'Policy','AttributeValue':policy([{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'sns:Publish','Resource':TOPIC,'Condition':{'ArnEquals':{'aws:SourceArn':TRAIL},'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])})
    R['subscription_arn']=call('subscribe-raw-queue','sns','subscribe',{'TopicArn':TOPIC,'Protocol':'sqs','Endpoint':R['queue_arn'],'Attributes':{'RawMessageDelivery':'true'},'ReturnSubscriptionArn':True})['SubscriptionArn']; save()
    call('read-encrypted-topic','sns','get-topic-attributes',{'TopicArn':TOPIC})
    call('read-raw-subscription','sns','get-subscription-attributes',{'SubscriptionArn':R['subscription_arn']})
    call('create-bucket','s3api','create-bucket',{'Bucket':PREFIX}); R['bucket']=PREFIX; save()
    call('bucket-source-policy','s3api','put-bucket-policy',{'Bucket':PREFIX,'Policy':policy([{'Sid':'Acl','Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'s3:GetBucketAcl','Resource':'arn:aws:s3:::'+PREFIX,'Condition':{'StringEquals':{'aws:SourceArn':TRAIL,'aws:SourceAccount':ACCOUNT}}},{'Sid':'Write','Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'s3:PutObject','Resource':'arn:aws:s3:::'+PREFIX+'/AWSLogs/'+ACCOUNT+'/*','Condition':{'StringEquals':{'aws:SourceArn':TRAIL,'aws:SourceAccount':ACCOUNT,'s3:x-amz-acl':'bucket-owner-full-control'}}}])})
    R['trail_attempted']=TRAIL; save()
    call('create-trail','cloudtrail','create-trail',{'Name':PREFIX,'S3BucketName':PREFIX,'SnsTopicName':TOPIC,'IncludeGlobalServiceEvents':False,'IsMultiRegionTrail':False,'EnableLogFileValidation':False,'IsOrganizationTrail':False}); R['trail_arn']=TRAIL; save()
    call('trail-status-preflight','cloudtrail','get-trail-status',{'Name':TRAIL})
    got=receive('validation-preflight',120)
    if not got:
        call('bounded-management-selectors','cloudtrail','put-event-selectors',{'TrailName':TRAIL,'EventSelectors':[{'ReadWriteType':'All','IncludeManagementEvents':True,'DataResources':[]}]})
        call('start-bounded-logging','cloudtrail','start-logging',{'Name':TRAIL})
        call('owned-management-trigger','sns','get-topic-attributes',{'TopicArn':TOPIC})
        got=receive('bounded-management-log-notification',600)
        call('trail-status-after-logging','cloudtrail','get-trail-status',{'Name':TRAIL})
    CAP['received_cloudtrail_publication']=got
    CAP['delivery_finished_ms']=ms(); save()
except Exception as e:
    CAP['failure']=str(e); save()
finally:
    if R.get('trail_attempted'):
        cleanup_one('stop-owned-trail','cloudtrail','stop-logging',{'Name':TRAIL})
        cleanup_one('delete-owned-trail','cloudtrail','delete-trail',{'Name':TRAIL})
        cleanup_one('verify-trail-absent','cloudtrail','get-trail',{'Name':TRAIL})
    if R.get('bucket'):
        listed=cleanup_one('list-owned-bucket-versions','s3api','list-object-versions',{'Bucket':PREFIX})
        versions=listed.get('output',{})
        objects=[{'Key':x['Key'],'VersionId':x['VersionId']} for x in versions.get('Versions',[])+versions.get('DeleteMarkers',[])]
        if objects: cleanup_one('delete-owned-versions','s3api','delete-objects',{'Bucket':PREFIX,'Delete':{'Objects':objects,'Quiet':False}})
        listed=cleanup_one('list-owned-bucket-objects','s3api','list-objects-v2',{'Bucket':PREFIX})
        objects=[{'Key':x['Key']} for x in listed.get('output',{}).get('Contents',[])]
        if objects: cleanup_one('delete-owned-objects','s3api','delete-objects',{'Bucket':PREFIX,'Delete':{'Objects':objects,'Quiet':False}})
        cleanup_one('verify-owned-bucket-versions-empty','s3api','list-object-versions',{'Bucket':PREFIX})
        cleanup_one('verify-owned-bucket-objects-empty','s3api','list-objects-v2',{'Bucket':PREFIX})
        cleanup_one('delete-owned-bucket','s3api','delete-bucket',{'Bucket':PREFIX})
        cleanup_one('verify-owned-bucket-absent','s3api','head-bucket',{'Bucket':PREFIX})
    if R.get('subscription_arn'):
        cleanup_one('unsubscribe-owned','sns','unsubscribe',{'SubscriptionArn':R['subscription_arn']})
        cleanup_one('verify-subscription-absent','sns','get-subscription-attributes',{'SubscriptionArn':R['subscription_arn']})
    if R.get('topic_arn'):
        cleanup_one('delete-owned-topic','sns','delete-topic',{'TopicArn':TOPIC})
        cleanup_one('verify-topic-absent','sns','get-topic-attributes',{'TopicArn':TOPIC})
    if R.get('queue_url'):
        cleanup_one('delete-owned-queue','sqs','delete-queue',{'QueueUrl':R['queue_url']})
        cleanup_one('verify-queue-absent','sqs','get-queue-attributes',{'QueueUrl':R['queue_url'],'AttributeNames':['QueueArn']})
    if R.get('key'):
        cleanup_one('schedule-owned-key-deletion','kms','schedule-key-deletion',{'KeyId':R['key']['KeyId'],'PendingWindowInDays':7})
        cleanup_one('verify-key-pending-deletion','kms','describe-key',{'KeyId':R['key']['KeyId']})
    CAP['cleanup_finished_ms']=ms(); save()

if R.get('key'):
    end=CAP.get('delivery_finished_ms',CAP['cleanup_finished_ms'])/1000
    args={'LookupAttributes':[{'AttributeKey':'EventSource','AttributeValue':'kms.amazonaws.com'}],'StartTime':datetime.datetime.fromtimestamp(START-5,datetime.timezone.utc).isoformat(),'EndTime':datetime.datetime.fromtimestamp(end+5,datetime.timezone.utc).isoformat(),'MaxResults':50}
    deadline=time.monotonic()+660; seen=set(); CAP['cloudtrail']['window']={'start':args['StartTime'],'end':args['EndTime'],'poll_started_ms':ms(),'maximum_poll_seconds':660}
    while True:
        page_args=dict(args)
        while True:
            started=ms(); res=observe('cloudtrail','lookup-events',page_args,ENV); ended=ms()
            lookup={'input':page_args,'request_started_ms':started,'response_observed_ms':ended,'result_code':res['code']}
            if res['code']!='Success': lookup['error']=res; CAP['cloudtrail']['lookups'].append(lookup); break
            out=res['output']; lookup.update(returned_event_count=len(out.get('Events',[])),next_token=out.get('NextToken'),matched_event_ids=[])
            for item in out.get('Events',[]):
                event=json.loads(item['CloudTrailEvent'])
                if R['key']['KeyId'] not in json.dumps(event): continue
                lookup['matched_event_ids'].append(event['eventID'])
                if event['eventID'] in seen: continue
                seen.add(event['eventID']); CAP['cloudtrail']['events'].append({'first_observed_ms':ended,'lookup_event':item,'event':event})
            CAP['cloudtrail']['lookups'].append(lookup); save()
            if not out.get('NextToken'): break
            page_args=dict(args,NextToken=out['NextToken']); time.sleep(0.6)
        crypt=[x['event'] for x in CAP['cloudtrail']['events'] if x['event'].get('eventName') in ['GenerateDataKey','Decrypt'] and not x['event'].get('errorCode') and (x['event'].get('requestParameters') or {}).get('encryptionContext',{}).get('aws:sns:topicArn')==TOPIC]
        print(json.dumps({'owned_kms_events':len(seen),'successful_crypto':[e['eventName'] for e in crypt]}),flush=True)
        if {'GenerateDataKey','Decrypt'}.issubset({e['eventName'] for e in crypt}) or time.monotonic()>=deadline: break
        time.sleep(min(30,max(0,deadline-time.monotonic())))
    CAP['cloudtrail']['window']['poll_finished_ms']=ms()
    CAP['findings']={'actual_cloudtrail_receipt':bool(CAP['receipts']),'successful_topic_kms_events':[{'event_id':e['eventID'],'event_time':e['eventTime'],'event_name':e['eventName'],'encryption_context':e['requestParameters']['encryptionContext'],'user_identity':e['userIdentity'],'source_ip_address':e['sourceIPAddress'],'user_agent':e['userAgent'],'key_resources':e.get('resources',[])} for e in crypt],'kms_permission_principal':'cloudtrail.amazonaws.com','sns_service_kms_allow':False,'trail_logging_started':any(o['operation']=='start-logging' and o.get('result',{}).get('code')=='Success' for o in CAP['observations'])}
    if not {'GenerateDataKey','Decrypt'}.issubset({e['eventName'] for e in crypt}): CAP['limitations'].append('Bounded management-history polling ended without both successful GenerateDataKey and Decrypt for the owned topic; absence beyond this window is not established.')
CAP['probe_source']={'filename':Path(__file__).name,'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'content':Path(__file__).read_text(),'aws_cli_helper_sha256':hashlib.sha256(Path('scripts/aws/aws_cli.py').read_bytes()).hexdigest()}
CAP['finished_ms']=ms(); save()
print(json.dumps({'fixture':str(OUT),'failure':CAP.get('failure'),'receipts':len(CAP['receipts']),'findings':CAP.get('findings')}),flush=True)
